import type { TestDef, Question } from './tests';

// Eslatma:
//  - ‹...› belgilari orasidagi matn PDF'da tagiga chizilgan (Exam'da <u> bilan ko'rsatiladi).
//  - ______ — savoldagi bo'sh joy.
//  - Javoblar kaliti matnli faylda yo'q edi: javoblar qo'lda yechib chiqilgan.
//    Rasmiy kalit (sat.org) bilan solishtirib chiqing.
//  - TEKSHIRILSIN (grafik rasmsiz yechilgan): Module 1 — 13; Module 2 — 13.
//  - TEKSHIRILSIN (tagi chizilgan qism taxminan belgilangan): Module 2 — 9.
//  - Module 1 — 6 va 7-savollar she'r: qator uzilishlari matnli faylda yo'qolgan, PDF bilan solishtiring.
//  - Math modullari hali kiritilmagan (matnli fayldagi formulalar buzilgan, grafiklar yo'q).
type C = [string, string, string, string];
const c = (a: string, b: string, cc: string, d: string): C => [a, b, cc, d];
const IMG = '/tests/img/t4-';

// ───────────── Reading & Writing — 1-modul ─────────────
const rw1: Question[] = [
  { passage: "The spacecraft OSIRIS-REx briefly made contact with the asteroid 101955 Bennu in 2020. NASA scientist Daniella DellaGiustina reports that despite facing the unexpected obstacle of a surface mostly covered in boulders, OSIRIS-REx successfully _______ a sample of the surface, gathering pieces of it to bring back to Earth.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("attached", "collected", "followed", "replaced"), answer: "B" },
  { passage: "Research conducted by planetary scientist Katarina Miljkovic suggests that the Moon’s surface may not accurately _______ early impact events. When the Moon was still forming, its surface was softer, and asteroid or meteoroid impacts would have left less of an impression; thus, evidence of early impacts may no longer be present.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("reflect", "receive", "evaluate", "mimic"), answer: "A" },
  { passage: "Handedness, a preferential use of either the right or left hand, typically is easy to observe in humans. Because this trait is present but less _______ in many other animals, animal-behavior researchers often employ tasks specially designed to reveal individual animals’ preferences for a certain hand or paw.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("recognizable", "intriguing", "significant", "useful"), answer: "A" },
  { passage: "It is by no means _______ to recognize the influence of Dutch painter Hieronymus Bosch on Ali Banisadr’s paintings; indeed, Banisadr himself cites Bosch as an inspiration. However, some scholars have suggested that the ancient Mesopotamian poem Epic of Gilgamesh may have had a far greater impact on Banisadr’s work.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("substantial", "satisfying", "unimportant", "appropriate"), answer: "C" },
  { passage: "The following text is adapted from Susan Glaspell’s 1912 short story “‘Out There.’” An elderly shop owner is looking at a picture that he recently acquired and hopes to sell.\n\nIt did seem that the picture failed to fit in with the rest of the shop. A persuasive young fellow who claimed he was closing out his stock let the old man have it for what he called a song. It was only a little out-of-the-way store which subsisted chiefly on the framing of pictures. The old man looked around at his views of the city, his pictures of cats and dogs, his flaming bits of landscape. “Don’t belong in here,” he fumed. And yet the old man was secretly proud of his acquisition. There was a hidden dignity in his scowling as he shuffled about pondering the least ridiculous place for the picture.", text: "Which choice best states the main purpose of the text?", choices: c("To reveal the shop owner’s conflicted feelings about the new picture", "To convey the shop owner’s resentment of the person he got the new picture from", "To describe the items that the shop owner most highly prizes", "To explain differences between the new picture and other pictures in the shop"), answer: "A" },
  { passage: "The following text is from the 1923 poem “Black Finger” by Angelina Weld Grimké, a Black American writer. A cypress is a type of evergreen tree.\n\nI have just seen a most beautiful thing, Slim and still, Against a gold, gold sky, A straight black cypress, Sensitive, Exquisite, A black finger Pointing upwards. Why, beautiful still finger, are you black? And why are you pointing upwards?", text: "Which choice best describes the overall structure of the text?", choices: c("The speaker assesses a natural phenomenon, then questions the accuracy of her assessment.", "The speaker describes a distinctive sight in nature, then ponders what meaning to attribute to that sight.", "The speaker presents an outdoor scene, then considers a human behavior occurring within that scene.", "The speaker examines her surroundings, then speculates about their influence on her emotional state."), answer: "B" },
  { passage: "The following text is from Walt Whitman’s 1860 poem “Calamus 24.”\n\nI HEAR it is charged against me that I seek to destroy institutions; But really I am neither for nor against institutions (What indeed have I in common with them?— Or what with the destruction of them?), Only I will establish in the Mannahatta [Manhattan] and in every city of These States, inland and seaboard, And in the fields and woods, and above every keel [ship] little or large, that dents the water, Without edifices, or rules, or trustees, or any argument, The institution of the dear love of comrades.", text: "Which choice best describes the overall structure of the text?", choices: c("The speaker questions an increasingly prevalent attitude, then summarizes his worldview.", "The speaker regrets his isolation from others, then predicts a profound change in society.", "The speaker concedes his personal shortcomings, then boasts of his many achievements.", "The speaker addresses a criticism leveled against him, then announces a grand ambition of his."), answer: "D" },
  { passage: "The mimosa tree evolved in East Asia, where the beetle Bruchidius terrenus preys on its seeds. In 1785, mimosa trees were introduced to North America, far from any B. terrenus. But evolutionary links between predators and their prey can persist across centuries and continents. Around 2001, B. terrenus was introduced in southeastern North America near where botanist Shu-Mei Chang and colleagues had been monitoring mimosa trees. Within a year, 93 percent of the trees had been attacked by the beetles.", text: "Which choice best describes the function of the third sentence in the overall structure of the text?", choices: c("It states the hypothesis that Chang and colleagues had set out to investigate using mimosa trees and B. terrenus.", "It presents a generalization that is exemplified by the discussion of the mimosa trees and B. terrenus.", "It offers an alternative explanation for the findings of Chang and colleagues.", "It provides context that clarifies why the species mentioned spread to new locations."), answer: "B" },
  { passage: "Text 1 Conventional wisdom long held that human social systems evolved in stages, beginning with hunter-gatherers forming small bands of members with roughly equal status. The shift to agriculture about 12,000 years ago sparked population growth that led to the emergence of groups with hierarchical structures: associations of clans first, then chiefdoms, and finally, bureaucratic states. Text 2 In a 2021 book, anthropologist David Graeber and archaeologist David Wengrow maintain that humans have always been socially flexible, alternately forming systems based on hierarchy and collective ones with decentralized leadership. The authors point to evidence that as far back as 50,000 years ago some hunter-gatherers adjusted their social structures seasonally, at times dispersing in small groups but also assembling into communities that included esteemed individuals.", text: "Based on the texts, how would Graeber and Wengrow (Text 2) most likely respond to the “conventional wisdom” presented in Text 1?", choices: c("By conceding the importance of hierarchical systems but asserting the greater significance of decentralized collective societies", "By disputing the idea that developments in social structures have followed a linear progression through distinct stages", "By acknowledging that hierarchical roles likely weren’t a part of social systems before the rise of agriculture", "By challenging the assumption that groupings of hunter-gatherers were among the earliest forms of social structure"), answer: "B" },
  { passage: "The following text is adapted from Frances Hodgson Burnett’s 1911 novel The Secret Garden. Mary, a young girl, recently found an overgrown hidden garden.\n\nMary was an odd, determined little person, and now she had something interesting to be determined about, she was very much absorbed, indeed. She worked and dug and pulled up weeds steadily, only becoming more pleased with her work every hour instead of tiring of it. It seemed to her like a fascinating sort of play.", text: "Which choice best states the main idea of the text?", choices: c("Mary hides in the garden to avoid doing her chores.", "Mary is getting bored with pulling up so many weeds in the garden.", "Mary is clearing out the garden to create a space to play.", "Mary feels very satisfied when she’s taking care of the garden."), answer: "D" },
  { passage: "The following text is from Ezra Pound’s 1909 poem “Hymn III,” based on the work of Marcantonio Flaminio.\n\nAs a fragile and lovely flower unfolds its gleaming foliage on the breast of the fostering earth, if the dew and the rain draw it forth; So doth my tender mind flourish, if it be fed with the sweet dew of the fostering spirit, Lacking this, it beginneth straightway to languish, even as a floweret born upon dry earth, if the dew and the rain tend it not.", text: "Based on the text, in what way is the human mind like a flower?", choices: c("It becomes increasingly vigorous with the passage of time.", "It draws strength from changes in the weather.", "It requires proper nourishment in order to thrive.", "It perseveres despite challenging circumstances."), answer: "C" },
  { passage: "The following text is adapted from Jack London’s 1903 novel The Call of the Wild. Buck is a sled dog living with John Thornton in Yukon, Canada.\n\nThornton alone held [Buck]. The rest of mankind was as nothing. Chance travellers might praise or pet him; but he was cold under it all, and from a too demonstrative man he would get up and walk away. When Thornton’s partners, Hans and Pete, arrived on the long-expected raft, Buck refused to notice them till he learned they were close to Thornton; after that he tolerated them in a passive sort of way, accepting favors from them as though he favored them by accepting.", text: "Which choice best states the main idea of the text?", choices: c("Buck has become less social since he began living with Thornton.", "Buck mistrusts humans and does his best to avoid them.", "Buck has been especially well liked by most of Thornton’s friends.", "Buck holds Thornton in higher regard than any other person."), answer: "D" },
  { passage: "Organic farming is a method of growing food that tries to reduce environmental harm by using natural forms of pest control and avoiding fertilizers made with synthetic materials. Organic farms are still a small fraction of the total farms in the United States, but they have been becoming more popular. According to the US Department of Agriculture, in 2016 California had between 2,600 and 2,800 organic farms and _______", text: "Which choice most effectively uses data from the graph to complete the text?", image: IMG + "m1-q13.png", choices: c("Washington had between 600 and 800 organic farms.", "New York had fewer than 800 organic farms.", "Wisconsin and Iowa each had between 1,200 and 1,400 organic farms.", "Pennsylvania had more than 1,200 organic farms."), answer: "C" },
  { passage: "Biologist Valentina Gómez-Bahamón and her team have investigated two subspecies of the fork-tailed flycatcher bird that live in the same region in Colombia, but one subspecies migrates south for part of the year, and the other doesn’t. The researchers found that, due to slight differences in feather shape, the feathers of migratory forked-tailed flycatcher males make a sound during flight that is higher pitched than that made by the feathers of nonmigratory males. The researchers hypothesize that fork-tailed flycatcher females are attracted to the specific sound made by the males of their own subspecies, and that over time the females’ preference will drive further genetic and anatomical divergence between the subspecies.", text: "Which finding, if true, would most directly support Gómez-Bahamón and her team’s hypothesis?", choices: c("The feathers located on the wings of the migratory fork-tailed flycatchers have a narrower shape than those of the nonmigratory birds, which allows them to fly long distances.", "Over several generations, the sound made by the feathers of migratory male fork-tailed flycatchers grows progressively higher pitched relative to that made by the feathers of nonmigratory males.", "Fork-tailed flycatchers communicate different messages to each other depending on whether their feathers create high-pitched or low-pitched sounds.", "The breeding habits of the migratory and nonmigratory fork-tailed flycatchers remained generally the same over several generations."), answer: "B" },
  { passage: "Ablation Rates for Three Elements in Cosmic Dust, by Dust Source\n\nElement | SPC | AST | HTC | OCC\niron | 20% | 28% | 90% | 98%\npotassium | 44% | 74% | 97% | 100%\nsodium | 45% | 75% | 99% | 100%\n\nEarth’s atmosphere is bombarded by cosmic dust originating from several sources: short-period comets (SPCs), particles from the asteroid belt (ASTs), Halley-type comets (HTCs), and Oort cloud comets (OCCs). Some of the dust’s material vaporizes in the atmosphere in a process called ablation, and the faster the particles move, the higher the rate of ablation. Astrophysicist Juan Diego Carrillo-Sánchez led a team that calculated average ablation rates for elements in the dust (such as iron and potassium) and showed that material in slower- moving SPC or AST dust has a lower rate than the same material in faster-moving HTC or OCC dust. For example, whereas the average ablation rate for iron from AST dust is 28%, the average rate for _______", text: "Which choice most effectively uses data from the table to complete the example?", choices: c("iron from SPC dust is 20%.", "sodium from OCC dust is 100%.", "iron from HTC dust is 90%.", "sodium from AST dust is 75%."), answer: "C" },
  { passage: "Art collectives, like the United States- and Vietnam- based collective The Propeller Group or Cuba’s Los Carpinteros, are groups of artists who agree to work together: perhaps for stylistic reasons, or to advance certain shared political ideals, or to help mitigate the costs of supplies and studio space. Regardless of the reasons, art collectives usually involve some collaboration among the artists. Based on a recent series of interviews with various art collectives, an arts journalist claims that this can be difficult for artists who are often used to having sole control over their work.", text: "Which quotation from the interviews best illustrates the journalist’s claim?", choices: c("“The first collective I joined included many amazingly talented artists, and we enjoyed each other’s company, but because we had a hard time sharing credit and responsibility for our work, the collective didn’t last.”", "“We work together, but that doesn’t mean that individual projects are equally the work of all of us. Many of our projects are primarily the responsibility of whoever originally proposed the work to the group.”", "“Having worked as a member of a collective for several years, it’s sometimes hard to recall what it was like to work alone without the collective’s support. But that support encourages my individual expression rather than limits it.”", "“Sometimes an artist from outside the collective will choose to collaborate with us on a project, but all of those projects fit within the larger themes of the work the collective does on its own.”"), answer: "A" },
  { passage: "Effects of Mycorrhizal Fungi on 3 Plant Species\n\nPlant species | Mycorrhizal host | Average mass of plants grown in soil containing mycorrhizal fungi (in grams) | Average mass of plants grown in soil treated to kill fungi (in grams)\nCorn | yes | 15.1 | 3.8\nMarigold | yes | 10.2 | 2.4\nBroccoli | no | 7.5 | 7\n\nMycorrhizal fungi in soil benefits many plants, substantially increasing the mass of some. A student conducted an experiment to illustrate this effect. The student chose three plant species for the experiment, including two that are mycorrhizal hosts (species known to benefit from mycorrhizal fungi) and one nonmycorrhizal species (a species that doesn’t benefit from and may even be harmed by mycorrhizal fungi). The student then grew several plants from each species both in soil containing mycorrhizal fungi and in soil that had been treated to kill mycorrhizal and other fungi. After several weeks, the student measured the plants’ average mass and was surprised to discover that _______", text: "Which choice most effectively uses data from the table to complete the statement?", choices: c("broccoli grown in soil containing mycorrhizal fungi had a slightly higher average mass than broccoli grown in soil that had been treated to kill fungi.", "corn grown in soil containing mycorrhizal fungi had a higher average mass than broccoli grown in soil containing mycorrhizal fungi.", "marigolds grown in soil containing mycorrhizal fungi had a much higher average mass than marigolds grown in soil that had been treated to kill fungi.", "corn had the highest average mass of all three species grown in soil that had been treated to kill fungi, while marigolds had the lowest."), answer: "A" },
  { passage: "Several artworks found among the ruins of the ancient Roman city of Pompeii depict a female figure fishing with a cupid nearby. Some scholars have asserted that the figure is the goddess Venus, since she is known to have been linked with cupids in Roman culture, but University of Leicester archaeologist Carla Brain suggests that cupids may have also been associated with fishing generally. The fact that a cupid is shown near the female figure, therefore, _______", text: "Which choice most logically completes the text?", choices: c("is not conclusive evidence that the figure is Venus.", "suggests that Venus was often depicted fishing.", "eliminates the possibility that the figure is Venus.", "would be difficult to account for if the figure is not Venus."), answer: "A" },
  { passage: "Literary agents estimate that more than half of all nonfiction books credited to a celebrity or other public figure are in fact written by ghostwriters, professional authors who are paid to write other _______ but whose names never appear on book covers.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("people’s stories", "peoples story’s", "peoples stories", "people’s story’s"), answer: "A" },
  { passage: "Like other amphibians, the wood frog (Rana sylvatica) is unable to generate its own heat, so during periods of subfreezing temperatures, it _______ by producing large amounts of glucose, a sugar that helps prevent damaging ice from forming inside its cells.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("had survived", "survived", "would survive", "survives"), answer: "D" },
  { passage: "After a spate of illnesses as a child, Wilma Rudolph was told she might never walk again. Defying all odds, Rudolph didn’t just walk, she _______ the 1960 Summer Olympics in Rome, she won both the 100- and 200-meter dashes and clinched first place for her team in the 4 ×100 -meter relay, becoming the first US woman to win three gold medals in a single Olympics.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("ran—fast—during", "ran—fast during", "ran—fast, during", "ran—fast. During"), answer: "D" },
  { passage: "In many of her landscape paintings from the 1970s and 1980s, Lebanese American artist Etel Adnan worked to capture the essence of California’s fog-shrouded Mount Tamalpais region through abstraction, using splotches of color to represent the area’s features. Interestingly, the triangle representing the mountain itself _______ among the few defined figures in her paintings.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("are", "have been", "were", "is"), answer: "D" },
  { passage: "Seneca sculptor Marie Watt’s blanket art comes in a range of shapes and sizes. In 2004, Watt sewed strips of blankets together to craft a 10-by-13-inch _______ in 2014, she arranged folded blankets into two large stacks and then cast them in bronze, creating two curving 18-foot-tall blue-bronze pillars.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("sampler later,", "sampler;", "sampler,", "sampler, later,"), answer: "B" },
  { passage: "African American Percy Julian was a scientist and entrepreneur whose work helped people around the world to see. Named in 1999 as one of the greatest achievements by a US chemist in the past hundred years, _______ led to the first mass-produced treatment for glaucoma.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("Julian synthesized the alkaloid physostigmine in 1935; it", "in 1935 Julian synthesized the alkaloid physostigmine, which", "Julian’s 1935 synthesis of the alkaloid physostigmine", "the alkaloid physostigmine was synthesized by Julian in 1935 and"), answer: "C" },
  { passage: "The Arctic-Alpine Botanic Garden in Norway and the Jardim Botânico of Rio de Janeiro in Brazil are two of many botanical gardens around the world dedicated to growing diverse plant _______ fostering scientific research; and educating the public about plant conservation.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("species, both native and nonnative,", "species, both native and nonnative;", "species; both native and nonnative,", "species both native and nonnative,"), answer: "B" },
  { passage: "Sociologist Alton Okinaka sits on the review board tasked with adding new sites to the Hawai‘i Register of Historic Places, which includes Pi‘ilanihale Heiau and the ‘Ōpaeka‘a Road Bridge. Okinaka doesn’t make such decisions _______ all historical designations must be approved by a group of nine other experts from the fields of architecture, archaeology, history, and Hawaiian culture.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("single-handedly, however;", "single-handedly; however,", "single-handedly, however,", "single-handedly however"), answer: "B" },
  { passage: "In 1968, US Congressman John Conyers introduced a bill to establish a national holiday in honor of Dr. Martin Luther King Jr. The bill didn’t make it to a vote, but Conyers was determined. He teamed up with Shirley Chisholm, the first Black woman to be elected to Congress, and they resubmitted the bill every session for the next fifteen years. _______ in 1983, the bill passed.", text: "Which choice completes the text with the most logical transition?", choices: c("Instead,", "Likewise,", "Finally,", "Additionally,"), answer: "C" },
  { passage: "Geoscientists have long considered Hawaii’s Mauna Loa volcano to be Earth’s largest shield volcano by volume, measuring approximately 74,000 cubic kilometers. _______ according to a 2020 study by local geoscientist Michael Garcia, Hawaii’s Pūhāhonu shield volcano is significantly larger, boasting a volume of about 148,000 cubic kilometers.", text: "Which choice completes the text with the most logical transition?", choices: c("Secondly,", "Consequently,", "Moreover,", "However,"), answer: "D" },
  { passage: "Samuel Coleridge-Taylor was a prominent classical music composer from England who toured the US three times in the early 1900s. The child of a West African father and an English mother, Coleridge- Taylor emphasized his mixed-race ancestry. For example, he referred to himself as Anglo-African. _______ he incorporated the sounds of traditional African music into his classical music compositions.", text: "Which choice completes the text with the most logical transition?", choices: c("In addition,", "Actually,", "However,", "Regardless,"), answer: "A" },
  { passage: "In 2019, researcher Patricia Jurado Gonzalez and food historian Nawal Nasrallah prepared a stew from a 4,000-year-old recipe found on a Mesopotamian clay tablet. When they tasted the dish, known as pašrūtum (“unwinding”), they found that it had a mild taste and inspired a sense of calm. _______ the researchers, knowing that dishes were sometimes named after their intended effects, theorized that the dish’s name, “unwinding,” referred to its function: to help ancient diners relax.", text: "Which choice completes the text with the most logical transition?", choices: c("Therefore,", "Alternately,", "Nevertheless,", "Likewise,"), answer: "A" },
  { passage: "While researching a topic, a student has taken the following notes:\n• Chemical leavening agents cause carbon dioxide to be released within a liquid batter, making the batter rise as it bakes.\n• Baking soda and baking powder are chemical leavening agents.\n• Baking soda is pure sodium bicarbonate.\n• To produce carbon dioxide, baking soda needs to be mixed with liquid and an acidic ingredient such as honey.\n• Baking powder is a mixture of sodium bicarbonate and an acid.\n• To produce carbon dioxide, baking powder needs to be mixed with liquid but not with an acidic ingredient.", text: "The student wants to emphasize a difference between baking soda and baking powder. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("To make batters rise, bakers use chemical leavening agents such as baking soda and baking powder.", "Baking soda and baking powder are chemical leavening agents that, when mixed with other ingredients, cause carbon dioxide to be released within a batter.", "Baking soda is pure sodium bicarbonate, and honey is a type of acidic ingredient.", "To produce carbon dioxide within a liquid batter, baking soda needs to be mixed with an acidic ingredient, whereas baking powder does not."), answer: "D" },
  { passage: "While researching a topic, a student has taken the following notes:\n• Soo Sunny Park is a Korean American artist who uses light as her primary medium of expression.\n• She created her work Unwoven Light in 2013.\n• Unwoven Light featured a chain-link fence fitted with iridescent plexiglass tiles.\n• When light passed through the fence, colorful prisms formed.", text: "The student wants to describe Unwoven Light to an audience unfamiliar with Soo Sunny Park. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("Park’s 2013 installation Unwoven Light, which included a chain-link fence and iridescent tiles made from plexiglass, featured light as its primary medium of expression.", "Korean American light artist Soo Sunny Park created Unwoven Light in 2013.", "The chain-link fence in Soo Sunny Park’s Unwoven Light was fitted with tiles made from iridescent plexiglass.", "In Unwoven Light, a 2013 work by Korean American artist Soo Sunny Park, light formed colorful prisms as it passed through a fence Park had fitted with iridescent tiles."), answer: "D" },
  { passage: "While researching a topic, a student has taken the following notes:\n• Cambodia’s Angkor Wat was built in the 1100s to honor the Hindu god Vishnu.\n• It has been a Buddhist temple since the sixteenth century.\n• Decorrelation stretch analysis is a novel digital imaging technique that enhances the contrast between colors in a photograph.\n• Archaeologist Noel Hidalgo Tan applied decorrelation stretch analysis to photographs he had taken of Angkor Wat’s plaster walls.\n• Tan’s analysis revealed hundreds of images unknown to researchers.", text: "The student wants to present Tan’s research to an audience unfamiliar with Angkor Wat. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("Tan photographed Angkor Wat’s plaster walls and then applied decorrelation stretch analysis to the photographs.", "Decorrelation stretch analysis is a novel digital imaging technique that Tan used to enhance the contrast between colors in a photograph.", "Using a novel digital imaging technique, Tan revealed hundreds of images hidden on the walls of Angkor Wat, a Cambodian temple.", "Built to honor a Hindu god before becoming a Buddhist temple, Cambodia’s Angkor Wat concealed hundreds of images on its plaster walls."), answer: "C" },
];

// ───────────── Reading & Writing — 2-modul ─────────────
const rw2: Question[] = [
  { passage: "The fashion resale market, in which consumers purchase secondhand clothing from stores and online sellers, generated nearly $30 billion globally in 2019. Expecting to see continued growth, some analysts _______ that revenues will more than double by 2028.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("produced", "denied", "worried", "predicted"), answer: "D" },
  { passage: "Artificially delivering biomolecules to plant cells is an important component of protecting plants from pathogens, but it is difficult to transmit biomolecules through the layers of the plant cell wall. Markita del Carpio Landry and her colleagues have shown that it may be possible to _______ this problem by transmitting molecules through carbon nanotubes, which can cross cell walls.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("conceptualize", "neglect", "illustrate", "overcome"), answer: "D" },
  { passage: "Particle physicists like Ayana Holloway Arce and Aida El-Khadra spend much of their time _______ what is invisible to the naked eye: using sophisticated technology, they closely examine the behavior of subatomic particles, the smallest detectable parts of matter.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("selecting", "inspecting", "creating", "deciding"), answer: "B" },
  { passage: "Anthropologist Kristian J. Carlson and colleagues examined the fossilized clavicle and shoulder bones of a 3.6-million-year-old early hominin known as “Little Foot.” They found that these bones were _______ the clavicle and shoulder bones of modern apes that are frequent climbers, such as gorillas and chimpanzees, suggesting that Little Foot had adapted to life in the trees.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("surpassed by", "comparable to", "independent of", "obtained from"), answer: "B" },
  { passage: "Rydra Wong, the protagonist of Samuel R. Delany’s 1966 novel Babel-17, is a poet, an occupation which, in Delany’s work, is not _______: nearly a dozen of the characters that populate his novels are poets or writers.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("infallible", "atypical", "lucrative", "tedious"), answer: "B" },
  { passage: "For a 2020 exhibition, photographer and neurobiologist Okunola Jeyifous _______ a series of new images based on a series of alphabet posters from the 1970s known as the “Black ABCs,” which featured Black children from Chicago. Jeyifous photographed the now-adult models and layered the photos over magnified images of the models’ cells, resulting in what he called “micro and macro portraiture.”", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("validated", "created", "challenged", "restored"), answer: "B" },
  { passage: "In addition to being an accomplished psychologist himself, Francis Cecil Sumner was a _______ increasing the opportunity for Black students to study psychology, helping to found the psychology department at Howard University, a historically Black university, in 1930.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("proponent of", "supplement to", "beneficiary of", "distraction for"), answer: "A" },
  { passage: "Whether the reign of a French monarch such as Hugh Capet or Henry I was historically consequential or relatively uneventful, its trajectory was shaped by questions of legitimacy and therefore cannot be understood without a corollary understanding of the factors that allowed the monarch to _______ his right to hold the throne.", text: "Which choice completes the text with the most logical and precise word or phrase?", choices: c("reciprocate", "annotate", "buttress", "disengage"), answer: "C" },
  { passage: "Some bird species don’t raise their own chicks. Instead, adult females lay their eggs in other nests, next to another bird species’ own eggs. ‹Female cuckoos have been seen quickly laying eggs in the nests of other bird species when those birds are out looking for food.› After the eggs hatch, the noncuckoo parents will typically raise the cuckoo chicks as if they were their own offspring, even if the cuckoos look very different from the other chicks.", text: "Which choice best describes the function of the underlined sentence in the text as a whole?", choices: c("It introduces a physical feature of female cuckoos that is described later in the text.", "It describes the appearance of the cuckoo nests mentioned earlier in the text.", "It offers a detail about how female cuckoos carry out the behavior discussed in the text.", "It explains how other birds react to the female cuckoo behavior discussed in the text."), answer: "C" },
  { passage: "Cats can judge unseen people’s positions in space by the sound of their voices and thus react with surprise when the same person calls to them from two different locations in a short span of time. Saho Takagi and colleagues reached this conclusion by measuring cats’ levels of surprise based on their ear and head movements while the cats heard recordings of their owners’ voices from two speakers spaced far apart. Cats exhibited a low level of surprise when owners’ voices were played twice from the same speaker, but they showed a high level of surprise when the voice was played once each from the two different speakers.", text: "According to the text, how did the researchers determine the level of surprise displayed by the cats in the study?", choices: c("They watched how each cat moved its ears and head.", "They examined how each cat reacted to the voice of a stranger.", "They studied how each cat physically interacted with its owner.", "They tracked how each cat moved around the room."), answer: "A" },
  { passage: "A student performs an experiment testing her hypothesis that a slightly acidic soil environment is more beneficial for the growth of the plant Brassica rapa parachinensis (a vegetable commonly known as choy sum) than a neutral soil environment. She plants sixteen seeds of choy sum in a mixture of equal amounts of coffee grounds (which are highly acidic) and potting soil and another sixteen seeds in potting soil without coffee grounds as the control for the experiment. The two groups of seeds were exposed to the same growing conditions and monitored for three weeks.", text: "Which finding, if true, would most directly weaken the student’s hypothesis?", choices: c("The choy sum planted in the soil without coffee grounds were significantly taller at the end of the experiment than the choy sum planted in the mixture of soil and coffee grounds.", "The choy sum grown in the soil without coffee grounds weighed significantly less at the end of the experiment than the choy sum grown in the mixture of soil and coffee grounds.", "The choy sum seeds planted in the soil without coffee grounds sprouted significantly later in the experiment than did the seeds planted in the mixture of soil and coffee grounds.", "Significantly fewer of the choy sum seeds planted in the soil without coffee grounds sprouted plants than did the seeds planted in the mixture of soil and coffee grounds."), answer: "A" },
  { passage: "“The Young Girl” is a 1920 short story by Katherine Mansfield. In the story, the narrator takes an unnamed seventeen-year-old girl and her younger brother out for a meal. In describing the teenager, Mansfield frequently contrasts the character’s pleasant appearance with her unpleasant attitude, as when Mansfield writes of the teenager, _______", text: "Which quotation from “The Young Girl” most effectively illustrates the claim?", choices: c("“I heard her murmur, ‘I can’t bear flowers on a table.’ They had evidently been giving her intense pain, for she positively closed her eyes as I moved them away.”", "“While we waited she took out a little, gold powder-box with a mirror in the lid, shook the poor little puff as though she loathed it, and dabbed her lovely nose.”", "“I saw, after that, she couldn’t stand this place a moment longer, and, indeed, she jumped up and turned away while I went through the vulgar act of paying for the tea.”", "“She didn’t even take her gloves off. She lowered her eyes and drummed on the table. When a faint violin sounded she winced and bit her lip again. Silence.”"), answer: "B" },
  { passage: "High levels of public uncertainty about which economic policies a country will adopt can make planning difficult for businesses, but measures of such uncertainty have not tended to be very detailed. Recently, however, economist Sandile Hlatshwayo analyzed trends in news reports to derive measures not only for general economic policy uncertainty but also for uncertainty related to specific areas of economic policy, like tax or trade policy. One revelation of her work is that a general measure may not fully reflect uncertainty about specific areas of policy, as in the case of the United Kingdom, where general economic policy uncertainty _______", text: "Which choice most effectively uses data from the graph to illustrate the claim?", image: IMG + "m2-q13.png", choices: c("aligned closely with uncertainty about tax and public spending policy in 2005 but differed from uncertainty about tax and public spending policy by a large amount in 2009.", "was substantially lower than uncertainty about tax and public spending policy each year from 2005 to 2010.", "reached its highest level between 2005 and 2010 in the same year that uncertainty about trade policy and tax and public spending policy reached their lowest levels.", "was substantially lower than uncertainty about trade policy in 2005 and substantially higher than uncertainty about trade policy in 2010."), answer: "A" },
  { passage: "Linguist Deborah Tannen has cautioned against framing contentious issues in terms of two highly competitive perspectives, such as pro versus con. According to Tannen, this debate-driven approach can strip issues of their complexity and, when used in front of an audience, can be less informative than the presentation of multiple perspectives in a noncompetitive format. To test Tannen’s hypothesis, students conducted a study in which they showed participants one of three different versions of local news commentary about the same issue. Each version featured a debate between two commentators with opposing views, a panel of three commentators with various views, or a single commentator.", text: "Which finding from the students’ study, if true, would most strongly support Tannen’s hypothesis?", choices: c("On average, participants perceived commentators in the debate as more knowledgeable about the issue than commentators in the panel.", "On average, participants perceived commentators in the panel as more knowledgeable about the issue than the single commentator.", "On average, participants who watched the panel correctly answered more questions about the issue than those who watched the debate or the single commentator did.", "On average, participants who watched the single commentator correctly answered more questions about the issue than those who watched the debate did."), answer: "C" },
  { passage: "King Lear is a circa 1606 play by William Shakespeare. In the play, the character of King Lear attempts to test his three daughters’ devotion to him. He later expresses regret for his actions, as is evident when he _______", text: "Which choice most effectively uses a quotation from King Lear to illustrate the claim?", choices: c("says of himself, “I am a man / more sinned against than sinning.”", "says during a growing storm, “This tempest will not give me leave to ponder / On things would hurt me more.”", "says to himself while striking his head, “Beat at this gate that let thy folly in / And thy dear judgement out!”", "says of himself, “I will do such things— / What they are yet, I know not; but they shall be / The terrors of the earth!”"), answer: "C" },
  { passage: "Many of William Shakespeare’s tragedies address broad themes that still appeal to today’s audiences. For instance, Romeo and Juliet, which is set in the Italy of Shakespeare’s time, tackles the themes of parents versus children and love versus hate, and the play continues to be read and produced widely around the world. But understanding Shakespeare’s so-called history plays can require a knowledge of several centuries of English history. Consequently, _______", text: "Which choice most logically completes the text?", choices: c("many theatergoers and readers today are likely to find Shakespeare’s history plays less engaging than the tragedies.", "some of Shakespeare’s tragedies are more relevant to today’s audiences than twentieth-century plays.", "Romeo and Juliet is the most thematically accessible of all Shakespeare’s tragedies.", "experts in English history tend to prefer Shakespeare’s history plays to his other works."), answer: "A" },
  { passage: "Ancestral Puebloans, the civilization from which present-day Pueblo tribes descended, emerged as early as 1500 B.C.E. in an area of what is now the southwestern United States and dispersed suddenly in the late 1200s C.E., abandoning established villages with systems for farming crops and turkeys. Recent analysis comparing turkey remains at Mesa Verde, one such village in southern Colorado, to samples from modern turkey populations in the Rio Grande Valley of north central New Mexico determined that the latter birds descended in part from turkeys cultivated at Mesa Verde, with shared genetic markers appearing only after 1280. Thus, researchers concluded that _______", text: "Which choice most logically completes the text?", choices: c("conditions of the terrains in the Rio Grande Valley and Mesa Verde had greater similarities in the past than they do today.", "some Ancestral Puebloans migrated to the Rio Grande Valley in the late 1200s and carried farming practices with them.", "Indigenous peoples living in the Rio Grande Valley primarily planted crops and did not cultivate turkeys before 1280.", "the Ancestral Puebloans of Mesa Verde likely adopted the farming practices of Indigenous peoples living in other regions."), answer: "B" },
  { passage: "One challenge when researching whether holding elected office changes a person’s behavior is the problem of ensuring that the experiment has an appropriate control group. To reveal the effect of holding office, researchers must compare people who hold elected office with people who do not hold office but who are otherwise similar to the office-holders. Since researchers are unable to control which politicians win elections, they therefore _______", text: "Which choice most logically completes the text?", choices: c("struggle to find valid data about the behavior of politicians who do not currently hold office.", "can only conduct valid studies with people who have previously held office rather than people who presently hold office.", "should select a control group of people who differ from office holders in several significant ways.", "will find it difficult to identify a group of people who can function as an appropriate control group for their studies."), answer: "D" },
  { passage: "In his groundbreaking book Bengali Harlem and the Lost Histories of South Asian America, Vivek Bald uses newspaper articles, census records, ships’ logs, and memoirs to tell the _______ who made New York City their home in the early twentieth century.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("story’s of the South Asian immigrants", "story’s of the South Asian immigrants’", "stories of the South Asian immigrants", "stories’ of the South Asian immigrant’s"), answer: "C" },
  { passage: "In her two major series “Memory Test” and “Autobiography,” painter Howardena Pindell explored themes _______ healing, self-discovery, and memory by cutting and sewing back together pieces of canvas and inserting personal artifacts, such as postcards, into some of the paintings.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("of", "of,", "of—", "of:"), answer: "A" },
  { passage: "Both Sona Charaipotra, an Indian American, and Dhonielle Clayton, an African American, grew up frustrated by the lack of diverse characters in books for young people. In 2011, these two writers joined forces to found CAKE Literary, a book packaging _______ specializes in the creation and promotion of stories told from diverse perspectives for children and young adults.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("company,", "company that", "company", "company, that"), answer: "B" },
  { passage: "A study led by scientist Rebecca Kirby at the University of Wisconsin–Madison found that black bears that eat human food before hibernation have increased levels of a rare carbon isotope, _______ due to the higher ¹³C levels in corn and cane sugar. Bears with these elevated levels were also found to have much shorter hibernation periods on average.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("carbon-13, (¹³C)", "carbon-13 (¹³C)", "carbon-13, (¹³C),", "carbon-13 (¹³C),"), answer: "D" },
  { passage: "In 2010, archaeologist Noel Hidalgo Tan was visiting the twelfth-century temple of Angkor Wat in Cambodia when he noticed markings of red paint on the temple _______ the help of digital imaging techniques, he discovered the markings to be part of an elaborate mural containing over 200 paintings.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("walls, with", "walls with", "walls so with", "walls. With"), answer: "D" },
  { passage: "24 Working from an earlier discovery of Charpentier’s, chemists Emmanuelle Charpentier and Jennifer Doudna—winners of the 2020 Nobel Prize in Chemistry—re-created and then reprogrammed the so-called “genetic scissors” of a species of DNA-cleaving bacteria _______ a tool that is revolutionizing the field of gene technology.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("to forge", "forging", "forged", "and forging"), answer: "B" },
  { passage: "In 2016, engineer Vanessa Galvez oversaw the installation of 164 bioswales, vegetated channels designed to absorb and divert stormwater, along the streets of Queens, New York. By reducing the runoff flowing into city sewers, _______", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("the mitigation of both street flooding and the resulting pollution of nearby waterways has been achieved by bioswales.", "the bioswales have mitigated both street flooding and the resulting pollution of nearby waterways.", "the bioswales’ mitigation of both street flooding and the resulting pollution of nearby waterways has been achieved.", "both street flooding and the resulting pollution of nearby waterways have been mitigated by bioswales."), answer: "B" },
  { passage: "A study published by Rice University geoscientist Ming Tang in 2019 offers a new explanation for the origin of Earth’s _______ structures called arcs, towering ridges that form when a dense oceanic plate subducts under a less dense continental plate, melts in the mantle below, and then rises and bursts through the continental crust above.", text: "Which choice completes the text so that it conforms to the conventions of Standard English?", choices: c("continents geological", "continents: geological", "continents; geological", "continents. Geological"), answer: "B" },
  { passage: "During a 2021 launch, Rocket Labs’ Electron rocket experienced an unexpected failure: its second-stage booster shut down suddenly after ignition. _______ instead of downplaying the incident, Rocket Labs’ CEO publicly acknowledged what happened and apologized for the loss of the rocket’s payload, which had consisted of two satellites.", text: "Which choice completes the text with the most logical transition?", choices: c("Afterward,", "Additionally,", "Indeed,", "Similarly,"), answer: "C" },
  { passage: "When soil becomes contaminated by toxic metals, it can be removed from the ground and disposed of in a landfill. _______ contaminated soil can be detoxified via phytoremediation: plants that can withstand high concentrations of metals absorb the pollutants and store them in their shoots, which are then cut off and safely disposed of, preserving the health of the plants.", text: "Which choice completes the text with the most logical transition?", choices: c("Alternatively,", "Specifically,", "For example,", "As a result,"), answer: "A" },
  { passage: "While researching a topic, a student has taken the following notes:\n• The calendar used by most of the world (the Gregorian calendar) has 365 days.\n• Because 365 days can’t be divided evenly by 7 (the number of days in a week), calendar dates fall on a different day of the week each year.\n• The Hanke-Henry permanent calendar, developed as an alternative to the Gregorian calendar, has 364 days.\n• Because 364 can be divided evenly by 7, calendar dates fall on the same day of the week each year, which supports more predictable scheduling.", text: "The student wants to explain an advantage of the Hanke-Henry calendar. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("The Gregorian calendar has 365 days, which is one day longer than the Hanke-Henry permanent calendar.", "Adopting the Hanke-Henry permanent calendar would help solve a problem with the Gregorian calendar.", "Designed so calendar dates would occur on the same day of the week each year, the Hanke-Henry calendar supports more predictable scheduling than does the Gregorian calendar.", "The Hanke-Henry permanent calendar was developed as an alternative to the Gregorian calendar, which is currently the most-used calendar in the world."), answer: "C" },
  { passage: "While researching a topic, a student has taken the following notes:\n• The Haudenosaunee Confederacy is a nearly 1,000-year-old alliance of six Native nations in the northeastern US.\n• The members are bound by a centuries-old agreement known as the Great Law of Peace.\n• Historian Bruce Johansen is one of several scholars who believe that the principles of the Great Law of Peace influenced the US Constitution.\n• This theory is called the influence theory.\n• Johansen cites the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy.", text: "The student wants to present the influence theory to an audience unfamiliar with the Haudenosaunee Confederacy. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("Historian Bruce Johansen believes that the Great Law of Peace was very influential.", "The influence theory is supported by the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy.", "The influence theory holds that the principles of the Great Law of Peace, a centuries-old agreement binding six Native nations in the northeastern US, influenced the US Constitution.", "Native people, including the members of the Haudenosaunee Confederacy, influenced the founding of the US in many different ways."), answer: "C" },
  { passage: "While researching a topic, a student has taken the following notes:\n• In 1999, astronomer Todd Henry studied the differences in surface temperature between the Sun and nearby stars.\n• His team mapped all stars within 10 parsecs (approximately 200 trillion miles) of the Sun.\n• The surface temperature of the Sun is around 9,800°F, which classifies it as a G star.\n• 327 of the 357 stars in the study were classified as K or M stars, with surface temperatures under 8,900°F (cooler than the Sun).\n• 11 of the 357 stars in the study were classified as A or F stars, with surface temperatures greater than 10,300°F (hotter than the Sun).", text: "The student wants to emphasize how hot the Sun is relative to nearby stars. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("At around 9,800°F, which classifies it as a G star, the Sun is hotter than most but not all of the stars within 10 parsecs of it.", "Astronomer Todd Henry determined that the Sun, at around 9,800°F, is a G star, and several other stars within a 10-parsec range are A or F stars.", "Of the 357 stars within ten parsecs of the Sun, 327 are classified as K or M stars, with surface temperatures under 8,900°F.", "While most of the stars within 10 parsecs of the Sun are classified as K, M, A, or F stars, the Sun is classified as a G star due to its surface temperature of 9,800°F."), answer: "A" },
  { passage: "28 While researching a topic, a student has taken the following notes:\n• The Atlantic Monthly magazine was first published in 1857.\n• The magazine focused on politics, art, and literature.\n• In 2019, historian Cathryn Halverson published the book Faraway Women and the “Atlantic Monthly.”\n• Its subject is female authors whose autobiographies appeared in the magazine in the early 1900s.\n• One of the authors discussed is Juanita Harrison.", text: "The student wants to introduce Cathryn Halverson’s book to an audience already familiar with the Atlantic Monthly. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("Cathryn Halverson’s Faraway Women and the “Atlantic Monthly” discusses female authors whose autobiographies appeared in the magazine in the early 1900s.", "A magazine called the Atlantic Monthly, referred to in Cathryn Halverson’s book title, was first published in 1857.", "Faraway Women and the “Atlantic Monthly” features contributors to the Atlantic Monthly, first published in 1857 as a magazine focusing on politics, art, and literature.", "An author discussed by Cathryn Halverson is Juanita Harrison, whose autobiography appeared in the Atlantic Monthly in the early 1900s."), answer: "A" },
  { passage: "While researching a topic, a student has taken the following notes:\n• The magnificent frigatebird (fregata magnificens) is a species of seabird that feeds mainly on fish, tuna, squid, and other small sea animals.\n• It is unusual among seabirds in that it doesn’t dive into the water for prey.\n• One way it acquires food is by using its hook-tipped bill to snatch prey from the surface of the water.\n• Another way it acquires food is by taking it from weaker birds by force.\n• This behavior is known as kleptoparasitism.", text: "The student wants to emphasize a similarity between the two ways a magnificent frigatebird acquires food. Which choice most effectively uses relevant information from the notes to accomplish this goal?", choices: c("A magnificent frigatebird never dives into the water, instead using its hook-tipped bill to snatch prey from the surface.", "Neither of a magnificent frigatebird’s two ways of acquiring food requires the bird to dive into the water.", "Of the magnificent frigatebird’s two ways of acquiring food, only one is known as kleptoparasitism.", "In addition to snatching prey from the water with its hook-tipped bill, a magnificent frigatebird takes food from other birds by force."), answer: "B" },
];

